// they can be recognized (and cleaned up) later without touching other anchors.
const CERT_FILE_PREFIX = 'podman-desktop-';

// The certificate stores queried from the host machine.
const CERTIFICATE_STORES: Array<'system' | 'bundled' | 'extra'> = ['system', 'bundled', 'extra'];

/**
 * Manages synchronization of host system TLS certificates into running Podman virtual machines.
 */
export class PodmanCertificateSync {
  constructor(
    private readonly machineStatuses: Map<string, extensionApi.ProviderConnectionStatus>,
    private readonly machineInfos: Map<string, MachineInfo>,
  ) {}

  /**
   * Retrieve the trusted certificates from the host machine, aggregating the
   * 'system', 'bundled' and 'extra' certificate stores and removing duplicates.
   */
  getSystemCertificates(): string[] {
    const seen = new Set<string>();

    for (const store of CERTIFICATE_STORES) {
      for (const certificate of tls.getCACertificates(store)) {
        seen.add(certificate);
      }
    }

    return [...seen];
  }

  /**
   * Return the names of the machines that are currently started and expose a
   * known VM type (a machine without a VM type cannot be reached over ssh).
   */
  getRunningMachineNames(): string[] {
    const names: string[] = [];

    for (const [name, status] of this.machineStatuses) {
      if (status !== 'started') {
        continue;
      }

      const vmType = this.machineInfos.get(name)?.vmType;
      if (!vmType) {
        continue;
      }

      names.push(name);
    }

    return names;
  }

  /**
   * Synchronize the host certificates into every running Podman machine. If one
   * machine fails to synchronize, the remaining machines are still processed.
   */
  async synchronizeAll(): Promise<void> {
    const runningMachines = this.getRunningMachineNames();

    if (runningMachines.length === 0) {
      await extensionApi.window.showWarningMessage('No running Podman machines found.');
      return;
    }

    const certificates = this.getSystemCertificates();

    for (const machineName of runningMachines) {
      try {
        await this.synchronize(machineName, certificates);
      } catch (error) {
        // Keep going with the other machines even if this one failed.
        console.error(`Certificate sync failed for machine ${machineName}:`, error);
      }
    }
  }

